mapper.select:
select b.BOOKSET_ID booksetId, b.BUSI_ID busiId, to_char(b.CDATE,'yyyy-mm-dd') cdate, b.RECAL_TYPE recalType, b.DAILYDSC_YIELD dailydscYield , to_char(b.DAILYDSC_YIELD,'FM999,999,999,999,999,990.000000000000') dailydscYieldFt from BOK_AMO_CONFIG b where 1=1
and b.BOOKSET_ID =#{booksetId}
and BUSI_ID = #{finprodId}
and CDATE <=to_date(#{vdateEnd},'yyyy-mm-dd')
and CDATE >=to_date(#{vdateBegin},'yyyy-mm-dd')
and b.RECAL_TYPE =#{recalType}

select distinct to_char(BOOKSET_DATE,'yyyy-mm-dd')
from BOK_BOOKSET_DATE
where BOOKSET_ID=#{booksetId}
